Lemma ds_mun : forall j Σk b ib ents i rest k s, rt_wfP Σk ((b, skipn i ents) :: rest) -> dl_sig p Σk ->
  nth_error (r_st (pr Σk 24)) ib = Some CkBatch -> b = p_abeg (l_SB (lay Σk)) 24 ib -> nth_error (sec Σk) k = Some s -> s_quar s = true ->
